class Solution {
  public int minOperationsMaxProfit(int[] customers, int boardingCost, int runningCost) {
    int waiting = 0, rotations = 0, boarded = 0, bestProfit = 0, bestRotation = -1;
    int i = 0;
    while (i < customers.length || waiting > 0) {
      if (i < customers.length) waiting += customers[i++];
      int onBoard = Math.min(4, waiting);
      waiting -= onBoard;
      boarded += onBoard;
      rotations++;
      int profit = boarded * boardingCost - rotations * runningCost;
      if (profit > bestProfit) {
        bestProfit = profit;
        bestRotation = rotations;
      }
    }
    return bestRotation;
  }
}
